_size":100,"_inline_size":null,"content_position_mobile":"center"},"elements":[{"id":"7aa1d30c","elType":"widget","settings":{"icon_list":[{"type":"custom","selected_icon":{"value":"far fa-user-circle","library":"fa-regular"},"_id":"632a43c","custom_date_format":"F j, Y","custom_time_format":"g:i a","custom_text":"دکتر علیرضا صدیق","show_icon":"custom"},{"selected_icon":{"value":"fas fa-calendar","library":"fa-solid"},"_id":"7cb024a","custom_date_format":"F j, Y","custom_time_format":"g:i a","date_format":"custom"}],"icon_align":"center","icon_color":"#FFFFFF","text_color":"#EFEFEF","icon_typography_typography":"custom","icon_typography_font_family":"IRANYekanFN","icon_typography_font_size":{"unit":"px","size":14,"sizes":[]},"icon_typography_font_size_mobile":{"unit":"px","size":12,"sizes":[]}},"elements":[],"widgetType":"post-info"}],"isInner":true}],"isInner":true}],"isInner":false}],"isInner":false},{"id":"15329e5a","elType":"section","settings":{"content_width":{"unit":"px","size":1113,"sizes":[]},"structure":"20","margin":{"unit":"px","top":"0","right":0,"bottom":"50","left":0,"isLinked":false}},"elements":[{"id":"5d537b28","elType":"column","settings":{"_column_size":50,"_inline_size":70},"elements":[{"id":"17bddaa","elType":"widget","settings":{"editor":"<section class="elementor-section elementor-inner-section elementor-element elementor-element-9221460 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="9221460" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-8f59cb4" data-id="8f59cb4" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-6e06150 elementor-widget elementor-widget-heading" data-id="6e06150" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h1 class="elementor-heading-title elementor-size-default">بلفاروپلاستی چیست؟</h1></div></div></div></div></div></section><div class="elementor-element elementor-element-4e3a432 elementor-widget elementor-widget-text-editor" data-id="4e3a432" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>بلفاروپلاستی نوعی جراحی است که روی پلک ها انجام می شود. این کار برای از بین بردن پوست اضافی پلک های بالایی و همچنین کاهش پف پلک های پایین انجام می شود. دلایل زیادی وجود دارد که ممکن است فرد دچار پف های زیر چشم، افتادگی پلک و سایر مشکلات زیبایی ناحیه چشم شود. افزایش سن در ناحیه چشم می‌تواند تاثیر زیادی بر حالت‌های چهره داشته باشد و اغلب حالتی خسته، بی حوصله یا حتی عصبانی ایجاد می‌کند. دیدن ظاهر خسته فرد می‌تواند نا امیدکننده باشد و بر عزت نفس تأثیر بگذارد. به بلفاروپلاستی، لیفت چشم نیز می گویند. بلفاروپلاستی فوقانی یک جراحی متمایز از جراحی پتوز پلک است که باعث بالا رفتن افتادگی پلک فوقانی می شود. بلفاروپلاستی اغلب نیاز به برداشتن پوست اضافی، ماهیچه و بافت چربی زیرین دارد، اما گاهی اوقات می‌توان بافت‌ها را به جای برداشتن، تغییر مکان داد.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-5d78560 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="5d78560" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-5ec9ecd" data-id="5ec9ecd" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-0e27921 elementor-widget elementor-widget-heading" data-id="0e27921" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">چرا بلفاروپلاستی انجام می شود؟</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-481e7fb elementor-widget elementor-widget-text-editor" data-id="481e7fb" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>این جراحی معمولا به دلایل زیبایی انجام می شود. بلفاروپلاستی همچنین یک راه موثر برای بهبود بینایی در افراد مسن است که افتادگی پلک بالایی آنها مانع بینایی آنها می شود. بلفاروپلاستی یا لیفت چشم باعث از بین بردن سیاهی زیر چشم و یا سایر چین و چروک های صورت نمی شود. این مشکلات اغلب با درمان های همچون بوتاکس، لایه برداری با لیزر، تزریق فیلر و لیفت صورت و…. انجام خواهد شد که در کنار جراحی بلفاروپلاستی امکان پذیر است.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-4d6c5e6 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="4d6c5e6" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-4f3560b" data-id="4f3560b" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-47a8d08 elementor-widget elementor-widget-heading" data-id="47a8d08" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">بلفاروپلاستی چه مشکلاتی را درمان می کند؟</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-deb6ce6 elementor-widget elementor-widget-text-editor" data-id="deb6ce6" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><ul><li>شل شدگی یا افتادگی پوست که چین‌خوردگی ایجاد می‌کند یا خط طبیعی پلک بالایی را از بین می برد و گاهی اوقات بینایی را نیز مختل می‌کند.</li><li>رسوبات چربی که به صورت پف کردگی در پلک ها ظاهر می شوند</li><li>کیسه های زیر چشم</li><li>افتادگی پلک های پایین که سفیدی زیر عنبیه را نمایان می کند</li><li>پوست اضافی و چین و چروک های ریز پلک پایین</li></ul></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-2799675 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="2799675" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-4cfac87" data-id="4cfac87" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-2c9c588 elementor-widget elementor-widget-heading" data-id="2c9c588" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h3 class="elementor-heading-title elementor-size-default">بلفاروپلاستی روشی برای درمان پیری پلک</h3></div></div></div></div></div></section><div class="elementor-element elementor-element-508bd51 elementor-widget elementor-widget-text-editor" data-id="508bd51" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>با افزایش سن، پوست به تدریج خاصیت ارتجاعی خود را از دست می دهد. فقدان خاصیت ارتجاعی به علاوه کشش مداوم ناشی از جاذبه باعث جمع شدن پوست اضافی روی پلک های بالا و پایین می شود. پوست اضافی در پلک پایین باعث ایجاد چین و چروک و برآمدگی می شود. در پلک های بالایی، یک چین اضافی از پوست می تواند روی مژه ها آویزان شود و مانع دید شود. چربی هایی که کره چشم را از جمجمه جدا می کند می تواند باعث برآمدگی در پلک های بالا و پایین شود. غشای نازکی که چربی را در جای خود نگه می دارد با افزایش سن ضعیف می شود و باعث آمدن چربی در پلک ها می شود.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-dc59fe9 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="dc59fe9" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-5664a09" data-id="5664a09" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-2985bd4 elementor-widget elementor-widget-heading" data-id="2985bd4" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">چه کسی کاندیدای خوب برای بلفاروپلاستی است؟</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-ab3edd9 elementor-widget elementor-widget-text-editor" data-id="ab3edd9" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>بهترین کاندیدها برای لیفت چشم افرادی هستند که از سلامت خوبی برخوردار هستند و ایده ای واقع بینانه از آنچه می خواهند دارند. اکثر افراد بالای ۳۵ سال به دنبال این درمان هستند، اما اگر پلک های باز یا افتادگی پلک در خانواده شما ارثی است، ممکن است تصمیم بگیرید که جراحی را زودتر انجام دهید.</p><p>جراحی پلک یا همان جراحی بلفاروپلاستی می تواند ظاهر شما را بهبود بخشد و به افزایش اعتماد به نفس شما کمک کند. با این حال، ممکن است باعث ایده آل شدن ظاهر شما نشود یا ساختار صورت شما را تغییر ندهد. قبل از اینکه تصمیم به عمل جراحی بگیرید، به اهداف خود فکر کنید و آنها را با جراح خود در میان بگذارید.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-c44d8bc elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="c44d8bc" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-9e0bf1a" data-id="9e0bf1a" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-e2f8e97 elementor-widget elementor-widget-heading" data-id="e2f8e97" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">بلفاروپلاستی پلک بالا</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-e152d7a elementor-widget elementor-widget-text-editor" data-id="e152d7a" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>با افزایش سن، کاهش تولید کلاژن و الاستین ممکن است منجر به افتادگی پوست پلک شود. به این مشکل، پتوز پلک می گویند. گاهی اوقات، فیبرهایی که ماهیچه‌های بازکننده چشم را به هم متصل می‌کنند، با افزایش سن جدا می‌شوند و باعث افتادگی پلک بالایی می‌شوند. این موضوع، بلفاروپتوز نامیده می شود و جراح پلاستیک شما می تواند با عمل بلفاروپلاستی فوقانی آن را ترمیم کند. همچنین ممکن است با افزایش سن به دلیل ضعیف شدن فیبرهای همبند، چربی از بافت نازک پلک فوقانی بیرون بزند و این منجر به پف کردگی و یا افتادگی پلک شود.</p><p>پتوز پلک نیز ممکن است در اثر افتادگی ابرو ایجاد شود. این کار برای اصلاح نیاز به لیفت ابرو دارد. علت (های) پتوز پلک برای جراح پلاستیک شما مهم است تا برای جراحی مناسب شما، برنامه ریزی کند. جراح پلاستیک شما نیز آزمایشاتی را برای ارزیابی وجود خشکی چشم انجام خواهد داد. در صورت داشتن خشکی چشم، جراح شما باید روش جراحی را اصلاح کند و شما را برای برنامه ریزی مناسب بعد از عمل آماده کند. میزان افتادگی پلک بالایی ممکن است به اندازه ای شدید باشد که بخشی از میدان بینایی شما را مسدود کند. این به موضوعی تبدیل می شود که از نظر پزشکی، درمان آن ضروری است. در این صورت ممکن است واجد شرایط پوشش بیمه باشید.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-6a2a401 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="6a2a401" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-b07e00b" data-id="b07e00b" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-c594563 elementor-widget elementor-widget-heading" data-id="c594563" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">مراحل انجام عمل بلفاروپلاستی</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-e1fe54a elementor-widget elementor-widget-text-editor" data-id="e1fe54a" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>اگر بلفاروپلاستی برای هر دو پلک بالا و پایین انجام شوند، معمولاً حدود 2 ساعت طول می کشد. پزشک شما به احتمال زیاد از بی حسی موضعی (مسکن تزریق شده در اطراف چشم) همراه با آرامبخش خوراکی و یا بیهوشی عمومی استفاده خواهد کرد. اگر این عمل را در بیمارستان یا مرکز جراحی انجام می دهید، به احتمال زیاد آرامبخش IV دریافت خواهید کرد. جراح معمولاً خطوط طبیعی پلک های شما را برش می دهد. از طریق این برش ها، جراح شما پوست را از بافت زیرین جدا می کند و چربی و پوست اضافی (و عضله را در صورت لزوم) از بین می برد. سپس جراح آن برش ها را با بخیه های بسیار کوچک می بندد. بخیه ها در پلک های بالایی به مدت 3-6 روز باقی می مانند. بسته به تکنیک مورد استفاده، پلک های پایین ممکن است نیاز به بخیه نداشته باشند.</p><p>جراحی پلک پایین ممکن است با استفاده از یکی از چندین تکنیک انجام شود. در یک روش، جراح شما برشی را در داخل پلک پایین شما ایجاد می کند تا چربی را از بین ببرد. آن برش قابل مشاهده نخواهد بود. سپس جراح شما می تواند خطوط ریز پوست را با استفاده از لیزر C02 یا اربیوم از بین ببرد. روش دیگر شامل برش در امتداد حاشیه مژه است. از طریق آن برش، جراح شما می تواند پوست اضافی، عضله شل و چربی را حذف کند. خط برش پس از مدت کوتاهی محو می شود. پس از هر یک از این روش ها، جراح شما ممکن است انجام لیزر را توصیه کند.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-3ab162e elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="3ab162e" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-f86430c" data-id="f86430c" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-d7e9d57 elementor-widget elementor-widget-heading" data-id="d7e9d57" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">نکات مهم بعد از جراحی بلفاروپلاستی</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-2644fb0 elementor-widget elementor-widget-text-editor" data-id="2644fb0" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>به احتمال زیاد بعد از عمل جراحی باید توسط فرد دیگری به خانه برده شوید. همچنین باید یکی از آشنایان شما شب عمل در کنار شما بماند. پزشک احتمالاً برای مرطوب نگه داشتن چشم‌هایتان پماد می‌ریزد و در حالی که در اتاق ریکاوری هستید، آن‌ها را با کمپرس سرد می‌پوشاند. بهتر است بعد از عمل جراحی، چند روز مرخصی بگیرید و فعالیت های خود را برای چند روز پس از جراحی محدود کنید تا زمانی که پلک های شما بهبود یابد. بلافاصله پس از جراحی، ممکن است مشکل دید شما از پماد باشد و به نور حساس باشید. در هفته اول ورزش شدید انجام ندهید یا خم نشوید. به مدت چند هفته از آرایش چشم و نوشیدن الکل خودداری کنید.</p><p>برخی از افراد پس از جراحی دچار خشکی چشم می شوند، اما این مشکل به ندرت بیش از ۲ هفته طول می کشد. اگر خشکی چشم بیش از ۲ هفته طول کشید، با پزشک خود تماس بگیرید. قرار دادن کیسه های یخ روی چشم ها و خوابیدن با سر بالا در شب اول بعد از جراحی توصیه می شود. پزشک دستورالعمل های دقیقی را برای مراقبت از خود، به شما می دهد.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-d5457af elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="d5457af" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-b48f35d" data-id="b48f35d" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-da3d557 elementor-widget elementor-widget-heading" data-id="da3d557" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">نتایج جراحی بلفاروپلاستی</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-2349bc2 elementor-widget elementor-widget-text-editor" data-id="2349bc2" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>جراحی پلک بالا حداقل برای ۵-۷ سال خوب است. جراحی پلک پایین به ندرت نیاز به تکرار دارد. البته چشمان شما پس از عمل همچنان پیر می شوند. اگر پلک های شما دوباره افتاد، لیفت پیشانی به جای لیفت چشم، ممکن است روش ارجح باشد.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-dc930cb elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="dc930cb" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-3607a49" data-id="3607a49" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-1a5315e elementor-widget elementor-widget-heading" data-id="1a5315e" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h3 class="elementor-heading-title elementor-size-default">ریکاوری بلفاروپلاستی</h3></div></div></div></div></div></section><div class="elementor-element elementor-element-aebd0ec elementor-widget elementor-widget-text-editor" data-id="aebd0ec" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>بعد از جراحی پلک بلفاروپلاستی، بخیه هایی در هر دو پلک خواهید داشت که تا یک هفته باقی می ماند. معمولاً ورم و گاهی کبودی وجود دارد، اما پلک های شما باید در عرض یک یا دو هفته طبیعی به نظر برسند.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-4fcddc7 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="4fcddc7" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-1c38571" data-id="1c38571" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-d1c4670 elementor-widget elementor-widget-heading" data-id="d1c4670" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h3 class="elementor-heading-title elementor-size-default">خودمراقبتی در منزل بعد از بلفاروپلاستی</h3></div></div></div></div></div></section><div class="elementor-element elementor-element-7e1152c elementor-widget elementor-widget-text-editor" data-id="7e1152c" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>توصیه های کلی خود مراقبتی شامل موارد زیر است:</p><ul><li>تمام دستورالعمل های مراقبتی را رعایت کنید. پماد چشم را طبق دستور پزشک بمالید.</li><li>انتظار می رود تا چند هفته درد و تورم اطراف چشم داشته باشید.</li><li>از هر گونه ضربه به چشم ها خودداری کنید. به عنوان مثال آن ها را مالش ندهید.</li><li>از کمپرس خنک برای کمک به ناراحتی و احساس خشکی چشم استفاده کنید.</li><li>از چشمان خود در برابر نور خورشید محافظت کنید تا زمانی که روند بهبودی کامل شود، این بسیار مهم است.</li><li>هرگونه خونریزی، درد شدید یا علائم غیرعادی را به پزشک خود گزارش دهید.</li></ul></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-c4c5f45 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="c4c5f45" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-7b80725" data-id="7b80725" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-50ce87d elementor-widget elementor-widget-heading" data-id="50ce87d" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">عوارض جراحی بلفاروپلاستی</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-72b9ee1 elementor-widget elementor-widget-text-editor" data-id="72b9ee1" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>عوارض و نتایج ناخواسته از بلفاروپلاستی نادر است، اما گاهی اوقات اتفاق می افتد. آنها می توانند شامل موارد زیر باشند:</p><ul><li>خون ریزی</li><li>عفونت</li><li>خشکی چشم</li><li>رنگ غیر طبیعی پلک ها</li><li>پوست پلک که به طور غیر طبیعی به داخل یا خارج چروک می شود</li><li>نمی توانید چشمان خود را به طور کامل ببندید</li><li>خط مژه پلک پایین کشیده می شود</li><li>از دست دادن احتمالی بینایی</li></ul><p>اگر هر یک از این عوارض را دارید، در اسرع وقت با پزشک خود تماس بگیرید.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-7da780e elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="7da780e" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-93a5692" data-id="93a5692" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-a61f0a9 elementor-widget elementor-widget-heading" data-id="a61f0a9" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">جایگزین جراحی بلفاروپلاستی چیست؟</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-926dbd0 elementor-widget elementor-widget-text-editor" data-id="926dbd0" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>هیچ جایگزین پزشکی دیگری برای بلفاروپلاستی وجود ندارد که بتواند موقعیت پلک ها را تغییر دهد یا تغییر شکل ایجاد کند. صحبت کردن با یک مشاور یا روانشناس ممکن است به شما کمک کند بر نگرانی های خود در مورد ظاهر خود غلبه کنید و ممکن است تصمیم بگیرید که خودتان را آنگونه که هستید دوست بدارید.</p></div></div><section class="elementor-section elementor-inner-section elementor-element elementor-element-e8f92f3 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="e8f92f3" data-element_type="section"><div class="elementor-container elementor-column-gap-default"><div class="elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-9629693" data-id="9629693" data-element_type="column" data-settings="{&quot;background_background&quot;:&quot;gradient&quot;}"><div class="elementor-widget-wrap elementor-element-populated"><div class="elementor-element elementor-element-54ddac5 elementor-widget elementor-widget-heading" data-id="54ddac5" data-element_type="widget" data-widget_type="heading.default"><div class="elementor-widget-container"><h2 class="elementor-heading-title elementor-size-default">مسائل پزشکی مرتبط با بلفاروپلاستی</h2></div></div></div></div></div></section><div class="elementor-element elementor-element-93b8f0e elementor-widget elementor-widget-text-editor" data-id="93b8f0e" data-element_type="widget" data-widget_type="text-editor.default"><div class="elementor-widget-container"><p>قبل از عمل بلفاروپلاستی، شما باید طیف وسیعی از مسائل پزشکی را با پزشک خود در میان بگذارید. از جمله موارد زیر:</p><p><strong>سلامت جسمانی:</strong> معاینه به پزشک شما کمک می کند تا تصمیم بگیرد که آیا این درمان برای شما مناسب است یا خیر.</p><p><strong>سابقه پزشکی</strong>: برخی از شرایط پزشکی و جراحی هایی که در گذشته انجام داده اید ممکن است بر تصمیم گیری در مورد این عمل تأثیرگذار باشد، از جمله نوع بیهوشی مورد استفاده. به ویژه، در صورت داشتن هر گونه بیماری چشمی مانند گلوکوم، خشکی چشم، خیس شدن چشم یا جدا شدن شبکیه، هرگونه اختلال تیروئید مانند بیماری گریوز و کم کاری یا پرکاری تیروئید، هر بیماری قلبی عروقی، دیابت، فشار خون بالا و … را باید به پزشک خود اطلاع دهید.</p><p><strong>معاینه چشم:</strong> ممکن است لازم باشد قبل از جراحی، توسط چشم پزشک یا متخصص چشم ارزیابی شوید.</p><p><strong>خطرات و عوارض احتمالی:</strong> مهم است که خطرات و عوارض را درک کنید تا بتوانید بررسی کنید که آیا بلفاروپلاستی برای شما مناسب است یا خیر.</p><p><strong>دارو:</strong> پزشک خود را در مورد هر دارویی که به طور منظم مصرف می کنید یا اخیرا مصرف کرده اید، از جمله داروهای بدون نسخه مانند روغن ماهی و مکمل های ویتامینی را به پزشک خود اطلاع دهید.</p><p><strong>واکنش های دارویی:</strong> اگر تا به حال واکنش بد یا عارضه جانبی از هر دارویی از جمله بیهوشی داشته اید به پزشک خود اطلاع دهید.</p><p><strong>آماده سازی برای جراحی:</strong> پزشک دستورالعمل های دقیقی را در مورد آنچه که باید در خانه انجام دهید تا برای جراحی آماده شوید به شما ارائه می دهد. به عنوان مثال، ممکن است به شما توصیه شود که یک داروی خاص مصرف کنید یا دوز داروی موجود را تغییر دهید. تمام دستورالعمل ها را به دقت دنبال کنید.</p></div></div>","typography_typography":"custom","typography_font_family":"IRANYekanFN","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_line_height":{"unit":"rem","size":2,"sizes":[]},"typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]}},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"7cc0fb6a","elType":"column","settings":{"_column_size":50,"_inline_size":30},"elements":[{"id":"2db1b149","elType":"section","settings":{"sticky":"top","sticky_parent":"yes"},"elements":[{"id":"2fa436d0","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"50cb5946","elType":"widget","settings":{"title":"فهرست مطالب","exclude_headings_by_selector":[],"marker_view":"bullets","hierarchical_view":"","background_color":"#F8F8F8","border_width":{"unit":"px","size":0,"sizes":[]},"border_rad