_size":100,"_inline_size":null,"content_position_mobile":"center"},"elements":[{"id":"5afa4503","elType":"widget","settings":{"icon_list":[{"type":"custom","selected_icon":{"value":"far fa-user-circle","library":"fa-regular"},"_id":"632a43c","custom_date_format":"F j, Y","custom_time_format":"g:i a","custom_text":"دکتر علیرضا صدیق","show_icon":"custom"},{"selected_icon":{"value":"fas fa-calendar","library":"fa-solid"},"_id":"7cb024a","custom_date_format":"F j, Y","custom_time_format":"g:i a","date_format":"custom"}],"icon_align":"center","icon_color":"#FFFFFF","text_color":"#EFEFEF","icon_typography_typography":"custom","icon_typography_font_family":"IRANYekanFN","icon_typography_font_size":{"unit":"px","size":14,"sizes":[]},"icon_typography_font_size_mobile":{"unit":"px","size":12,"sizes":[]}},"elements":[],"widgetType":"post-info"}],"isInner":true}],"isInner":true}],"isInner":false}],"isInner":false},{"id":"7284102c","elType":"section","settings":{"content_width":{"unit":"px","size":1113,"sizes":[]},"structure":"20","margin":{"unit":"px","top":"0","right":0,"bottom":"50","left":0,"isLinked":false}},"elements":[{"id":"1131df53","elType":"column","settings":{"_column_size":50,"_inline_size":70},"elements":[{"id":"44234e87","elType":"widget","settings":{"editor":"<h1>جراحی زیبایی بینی</h1><p>جراحی زیبایی بینی یک روش جراحی است که با هدف تغییر شکل یا اندازه بینی انجام می‌شود. این روش ممکن است شامل کاهش یا افزایش اندازه بینی، تغییر شکل نوک بینی یا تنظیم زاویه بینی باشد.</p><h2>در چه مواردی باید انجام داد؟</h2><p>مواردی که ممکن است نیازمند جراحی زیبایی بینی باشند شامل موارد زیر باشد:</p><ol><li>تغییر شکل بینی به دلیل ضایعات یا صدمات</li><li>ناراحتی و افسردگی ناشی از شکل و اندازه بینی</li><li>مشکلات تنفسی ناشی از آناتومی نامناسب بینی</li></ol><h2>آیا مشکلات نفسی در زیبایی بینی رفع میشود ؟</h2><p>بله، جراحی زیبایی بینی می‌تواند در مواردی که مشکلات تنفسی نیز وجود دارد، مانند بستری وضعیت پروانه، درمان مشکلات نفسی ناشی از آناتومی نامناسب بینی را فراهم آورد.</p><h2>فواید جراحی بینی ؟</h2><p>در مورد فواید جراحی بینی، این عمل می‌تواند به تغییر شکل ظاهر بینی کمک کند و باعث اعتماد به‌نفس و راحتی روانی بیشتر در فرد شود. همچنین، در صورت وجود مشکلات تنفسی، جراحی بینی ممکن است به بهبود تنفس بینی کمک کند.</p><h2>توصیه جراح در مورد جراحی بینی ؟</h2><p>پزشک ممکن است نیازمند بررسی دقیق و مشاوره قبل از جراحی بینی باشد تا در خصوص آمادگی بیمار و توقعاتش از عمل جراحی و همچنین نیازهایش مشاوره کند. نکات مرتبط با شرایط فعلی بینی، بیماری‌های همراه، و انتظارات بیمار نیز باید مورد بحث قرار گیرد.</p>","typography_typography":"custom","typography_font_family":"IRANYekanFN","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_line_height":{"unit":"rem","size":2,"sizes":[]},"typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]}},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"3bf7a760","elType":"column","settings":{"_column_size":50,"_inline_size":30},"elements":[{"id":"72a5e40e","elType":"section","settings":{"sticky":"top","sticky_parent":"yes"},"elements":[{"id":"5463a081","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"2adba38a","elType":"widget","settings":{"title":"فهرست مطالب","exclude_headings_by_selector":[],"marker_view":"bullets","hierarchical_view":"","background_color":"#F8F8F8","border_width":{"unit":"px","size":0,"sizes":[]},"border_radius":{"unit":"px","size":15,"sizes":[]},"box_shadow_box_shadow_type":"yes","box_shadow_box_shadow":{"horizontal":0,"vertical":0,"blur":6,"spread":0,"color":"rgba(0, 0, 0, 0.14)"},"header_text_color":"#FFFFFF","header_typography_typography":"custom","header_typography_font_family":"IRANYekanFN","header_typography_font_size":{"unit":"px","size":16,"sizes":[]},"toggle_button_color":"#FEFEFE","list_typography_typography":"custom","list_typography_font_family":"IRANYekanFN","list_typography_font_size":{"unit":"px","size":12,"sizes":[]},"list_typography_line_height":{