ررسی کامل شرایط بیمار و همچنین سلامتی بیمار مشاوره کاردارد.</p><h2>پروتز گونه مناسب برای چه کسانی است</h2><p>پروتز گونه برای افرادی مناسب است که عیوب یا نقصی در گونه دارند یا مایل به افزایش حجم و شکل گونه‌های خود برای زیبایی نیاز دارند. همچنین افرادی که به دلایل طبی یا زیبایی نیاز به مشاوره برای انجام پروتز گونه دارند.</p>","typography_typography":"custom","typography_font_family":"IRANYekanFN","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_line_height":{"unit":"rem","size":2,"sizes":[]},"typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]}},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"5acfd6d2","elType":"column","settings":{"_column_size":50,"_inline_size":30},"elements":[{"id":"49236c3e","elType":"section","settings":{"sticky":"top","sticky_parent":"yes"},"elements":[{"id":"3e319764","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"418d6565","elType":"widget","settings":{"title":"فهرست مطالب","exclude_headings_by_selector":[],"marker_view":"bullets","hierarchical_view":"","background_color":"#F8F8F8","border_width":{"unit":"px","size":0,"sizes":[]},"border_radius":{"unit":"px","size":15,"sizes":[]},"box_shadow_box_shadow_type":"yes","box_shadow_box_shadow":{"horizontal":0,"vertical":0,"blur":6,"spread":0,"color":"rgba(0, 0, 0, 0.14)"},"header_text_color":"#FFFFFF","header_typography_typography":"custom","header_typography_font_family":"IRANYekanFN","header_typography_font_size":{"unit":"px","size":16,"sizes":[]},"toggle_button_color":"#FEFEFE","list_typography_typography":"custom","list_typography_font_family":"IRANYekanFN","list_typography_font_size":{"unit":"px","size":12,"sizes":[]},"list_typography_line_height":{"unit":"rem","size":2,"sizes":[]},"list_typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"list_typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]},"hide_t