n_size":100,"_inline_size":null,"content_position_mobile":"center"},"elements":[{"id":"2e1e1cb2","elType":"widget","settings":{"icon_list":[{"type":"custom","selected_icon":{"value":"far fa-user-circle","library":"fa-regular"},"_id":"632a43c","custom_date_format":"F j, Y","custom_time_format":"g:i a","custom_text":"دکتر علیرضا صدیق","show_icon":"custom"},{"selected_icon":{"value":"fas fa-calendar","library":"fa-solid"},"_id":"7cb024a","custom_date_format":"F j, Y","custom_time_format":"g:i a","date_format":"custom"}],"icon_align":"center","icon_color":"#FFFFFF","text_color":"#EFEFEF","icon_typography_typography":"custom","icon_typography_font_family":"IRANYekanFN","icon_typography_font_size":{"unit":"px","size":14,"sizes":[]},"icon_typography_font_size_mobile":{"unit":"px","size":12,"sizes":[]}},"elements":[],"widgetType":"post-info"}],"isInner":true}],"isInner":true}],"isInner":false}],"isInner":false},{"id":"1d02c06a","elType":"section","settings":{"content_width":{"unit":"px","size":1113,"sizes":[]},"structure":"20","margin":{"unit":"px","top":"0","right":0,"bottom":"50","left":0,"isLinked":false}},"elements":[{"id":"a828eeb","elType":"column","settings":{"_column_size":50,"_inline_size":70},"elements":[{"id":"533911bf","elType":"widget","settings":{"editor":"<h1>بوکال فت</h1><p>بوکال فت یک جراحی زمینه‌ای است که برای اصلاح شکل یا اندازه گونه یا لب برای افزایش حجم یا اصلاح شکل این نواحی استفاده می‌شود. این نوع پروتزات یا فیلرها با استفاده از موادی مانند سیلیکون، پلیمرهای رزینی، یا ژل‌های هیالورونیک وارد این ناحیه شده و شکل مرغوب و زیبایی خاصی به لب و گونه‌ها می‌دهند.</p><h2>روش انجام بوکال فت</h2><p>بوکال فت به صورت تزریق مستقیم به ناحیه مورد نظر انجام می‌شود. پزشک متخصص بوتاکس ممکن است از کانول یا سوزن برای تزریق مواد به ناحیه مورد نظر استفاده کند.</p><h2>توصیه پزشک</h2><p>تزریق بوکال فت نیازمند تخصص و دقت بالای پزشک متخصص است، بنابراین توصیه می‌شود قبل از تصمیم‌گیری برای انجام این روش، از یک پزشک متخصص و متعهد مشاوره و راهنمایی دریافت کنید.</p><h2>بوکال فت مناسب برای چه کسانی است</h2><p>بوکال فت برای افرادی مناسب است که مایل به افزایش حجم گونه یا لب یا اصلاح شکل این نواحی هستند. این روش برای ایجاد یک شکلبندی ایده‌آل و افزایش جذابیت صورت برای تعادل زیبایی و شکل دهی صورت مورد استفاده قرار می‌گیرد.</p>","typography_typography":"custom","typography_font_family":"IRANYekanFN","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_line_height":{"unit":"rem","size":2,"sizes":[]},"typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]}},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"2aea6106","elType":"column","settings":{"_column_size":50,"_inline_size":30},"elements":[{"id":"4c60b18c","elType":"section","settings":{"sticky":"top","sticky_parent":"yes"},"elements":[{"id":"580c1827","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"5146bcc4","elType":"widget","settings":{"title":"فهرست مطالب","exclude_headings_by_selector":[],"marker_view":"bullets","hierarchical_view":"","background_color":"#F8F8F8","border_width":{"unit":"px","size":0,"sizes":[]},"border_radius":{"unit":"px","size":15,"sizes":[]},"box_shadow_box_shadow_type":"yes","box_shadow_box_shadow":{"horizontal":0,"vertical":0,"blur":6,"spread":0,"color":"rgba(0, 0, 0, 0.14)"},"header_text_color":"#FFFFFF","header_typography_typography":"custom","header_typography_font_family":"IRANYekanFN","header_typography_font_size":{"unit":"px","size":16,"sizes":[]},"toggle_button_color":"#FEFEFE","list_typography_typography":"custom","list_typography_font_family":"IRANYekanFN","list_typography_font_size":{"unit":"px","size":12,"sizes":[]},"list_typography_line_height":{"unit":"rem","size":2,"sizes":[]},"list_typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"list_typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]},"hide_tablet":"hidden-tablet","hide_mobile":"hidden-mobile","__globals__":{"header_backgr