_size":100,"_inline_size":null,"content_position_mobile":"center"},"elements":[{"id":"592daa24","elType":"widget","settings":{"icon_list":[{"type":"custom","selected_icon":{"value":"far fa-user-circle","library":"fa-regular"},"_id":"632a43c","custom_date_format":"F j, Y","custom_time_format":"g:i a","custom_text":"دکتر علیرضا صدیق","show_icon":"custom"},{"selected_icon":{"value":"fas fa-calendar","library":"fa-solid"},"_id":"7cb024a","custom_date_format":"F j, Y","custom_time_format":"g:i a","date_format":"custom"}],"icon_align":"center","icon_color":"#FFFFFF","text_color":"#EFEFEF","icon_typography_typography":"custom","icon_typography_font_family":"IRANYekanFN","icon_typography_font_size":{"unit":"px","size":14,"sizes":[]},"icon_typography_font_size_mobile":{"unit":"px","size":12,"sizes":[]}},"elements":[],"widgetType":"post-info"}],"isInner":true}],"isInner":true}],"isInner":false}],"isInner":false},{"id":"1e25d18b","elType":"section","settings":{"content_width":{"unit":"px","size":1113,"sizes":[]},"structure":"20","margin":{"unit":"px","top":"0","right":0,"bottom":"50","left":0,"isLinked":false}},"elements":[{"id":"1ef279fc","elType":"column","settings":{"_column_size":50,"_inline_size":70},"elements":[{"id":"478874c4","elType":"widget","settings":{"editor":"<h1>لیفت ابرو و شقیقه</h1><p>لیفت ابرو و شقیقه یک روش جراحی زیبایی است که برای کشیدن و محکم کردن محدوده ابرو و کاهش پوست اضافی در اطراف چشم به منظور ایجاد انعطاف و جوانسازی پوست انجام می‌شود. این روش بهبودی ظاهری مشخصی برای منطقه چشم و ابرو پوست برای افراد بویژهی می‌باشد.</p><h2>روش انجام لیفت ابرو و شقیقه </h2><p>به منظور انجام لیفت ابرو و شقیقه، تکنیک‌های جراحی یا غیرجراحی از جمله جراحی پلکیادرمای تحتانی، سوزنی یا کاتریژ در کنار بهره‌های اختصاصی اعمال می‌شود.</p><h2>انواع لیفت ابرو و شقیقه</h2><p>این روش ممکن است شامل لیفت مینی(لیفت مینی فیس)، لیفت میدل (لیفت میدل فیس)، لیفت پانک فیس (لیفت پانک فیس) و یا لیفت شقیقه شامل لیفت اپتومی (لیفت میلینوپلاستی) و اپتوبلاستی باشند.</p><h2>توصیه پزشک</h2><p>پزشک برای انجام لیفت ابرو و شقیقه از نظر توانایی‌های بالینی، مهارت تجارب و دقت پزشک مورد نیاز می‌باشد و به شدت به توانایی تخصصی پزشک برای این موضوع و شرایط عمومی بیمار و محدوده ابرو و شقیقه ارچ.</p><h2>لیفت ابرو و شقیقه مناسب برای چه کسانی است</h2><p>لیفت ابرو و شقیقه مناسب برای افرادی است که از کاهش انعطاف و جوانه پوست برای برطرف کردن موهبت زیر چشم شکایت دارند و مایل به اصلاح شکل ابرو شکایت دارند.</p>","typography_typography":"custom","typography_font_family":"IRANYekanFN","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_line_height":{"unit":"rem","size":2,"sizes":[]},"typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]}},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"1dc623cf","elType":"column","settings":{"_column_size":50,"_inline_size":30},"elements":[{"id":"6f6aa416","elType":"section","settings":{"sticky":"top","sticky_parent":"yes"},"elements":[{"id":"473412f8","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"49266385","elType":"widget","settings":{"title":"فهرست مطالب","exclude_headings_by_selector":[],"marker_view":"bullets","hierarchical_view":"","background_color":"#F8F8F8","border_width":{"unit":"px","size":0,"sizes":[]},"border_radius":{"unit":"px","size":15,"sizes":[]},"box_shadow_box_shadow_type":"yes","box_shadow_box_shadow":{"horizontal":0,"vertical":0,"blur":6,"spread":0,"color":"rgba(0, 0, 0, 0.14)"},"header_text_color":"#FFFFFF","header_typography_typography":"custom","header_typography_font_family":"IRANYekanFN","header_typography_font_size":{"unit":"px","size":16,"sizes":[]},"toggle_button_color":"#FEFEFE","list_typography_typography":"custom","list_typography_font_family":"IRANYekanFN","list_typography_font_size":{"unit":"px","size":12,"sizes":[]},"list_typography_line_height":{"unit":"rem","size":2,"sizes":[]},"list_typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"list_typ