n_size":100,"_inline_size":null,"content_position_mobile":"center"},"elements":[{"id":"63730e62","elType":"widget","settings":{"icon_list":[{"type":"custom","selected_icon":{"value":"far fa-user-circle","library":"fa-regular"},"_id":"632a43c","custom_date_format":"F j, Y","custom_time_format":"g:i a","custom_text":"دکتر علیرضا صدیق","show_icon":"custom"},{"selected_icon":{"value":"fas fa-calendar","library":"fa-solid"},"_id":"7cb024a","custom_date_format":"F j, Y","custom_time_format":"g:i a","date_format":"custom"}],"icon_align":"center","icon_color":"#FFFFFF","text_color":"#EFEFEF","icon_typography_typography":"custom","icon_typography_font_family":"IRANYekanFN","icon_typography_font_size":{"unit":"px","size":14,"sizes":[]},"icon_typography_font_size_mobile":{"unit":"px","size":12,"sizes":[]}},"elements":[],"widgetType":"post-info"}],"isInner":true}],"isInner":true}],"isInner":false}],"isInner":false},{"id":"2dbfe5d4","elType":"section","settings":{"content_width":{"unit":"px","size":1113,"sizes":[]},"structure":"20","margin":{"unit":"px","top":"0","right":0,"bottom":"50","left":0,"isLinked":false}},"elements":[{"id":"18df0407","elType":"column","settings":{"_column_size":50,"_inline_size":70},"elements":[{"id":"2ea948d","elType":"widget","settings":{"editor":"<h1>لیفت صورت</h1><p>لیفت صورت یک روش جراحی زمینهای است که برای کشیدن و محکم کردن پوست صورت و گردن به منظور بهبود انعطاف و جوانه پوست استفاده می‌شود. این روش ممکن است برای افرادی که با نشانه‌های پیری پوست روبرو هستند مناسب باشد.</p><h2>روش انجام لیفت صورت</h2><p>لیفت صورت ممکن است به صورت جراحی یا با استفاده از تکنیک‌های غیرجراحی نظیر لیزر، رادیو فرکانسی و الکتروپریشن انجام شود. در روش جراحی، پوست و بافت زیرین کشیده و محکم می‌شود که باعث کشیده شدن طبیعی منطقه مورد نظر (معمولاً وسط‌صورت، گردن، واژن و یا فک) می‌شود.</p><h2>انواع لیفت صورت</h2><p>لیفت صورت شامل انواع مختلف که از جمله آن‌ها می‌توان به لیفت تمپل، لیفت حاشیه چشم، و یا لیفت گردن اشاره کرد.</p><h2>توصیه پزشک</h2><p>پزشک معمولاً برای انجام لیفت صورت بر اساس شرایط و نیاز شخصی افراد، میزان تجربه و دقت برداشته و همچنین بهترین روش ممکن را به آن‌ها توصیه می‌کند.</p><h2>لیفت صورت مناسب برای چه کسانی است</h2><p>لیفت صورت برای افرادی که از پیری پوست روی صورت شکایت دارند و مایل به بهبود انعطاف و جوانه پوست هستند مناسب خواهد بود.</p>","typography_typography":"custom","typography_font_family":"IRANYekanFN","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_line_height":{"unit":"rem","size":2,"sizes":[]},"typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]}},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"37f984dd","elType":"column","settings":{"_column_size":50,"_inline_size":30},"elements":[{"id":"57aa37c9","elType":"section","settings":{"sticky":"top","sticky_parent":"yes"},"elements":[{"id":"236cefcb","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"6dcddd9b","elType":"widget","settings":{"title":"فهرست مطالب","exclude_headings_by_selector":[],"marker_view":"bullets","hierarchical_view":"","background_color":"#F8F8F8","border_width":{"unit":"px","size":0,"sizes":[]},"border_radius":{"unit":"px","size":15,"sizes":[]},"box_shadow_box_shadow_type":"yes","box_shadow_box_shadow":{"horizontal":0,"vertical":0,"blur":6,"spread":0,"color":"rgba(0, 0, 0, 0.14)"},"header_text_color":"#FFFFFF","header_typography_typography":"custom","header_typography_font_family":"IRANYekanFN","header_typography_font_size":{"unit":"px","size":16,"sizes":[]},"toggle_button_color":"#FEFEFE","list_typography_typography":"custom","list_typography_font_family":"IRANYekanFN","list_typography_font_size":{"unit":"px","size":12,"sizes":[]},"list_typography_line_height":{"unit":"rem","size":2,"sizes":[]},"list_typography_line_height_tablet":{"unit":"rem","size":"","sizes":[]},"list_typography_line_height_mobile":{"unit":"rem","size":"","sizes":[]},"hide_tablet":"hidden-tablet","hide_mobile":"hidden-